reference_solution:
def longest_run(values):
    if len(values) == 0:
        return 0
    longest = 1
    current = 1
    for i in range(1, len(values)):
        if values[i] == values[i - 1]:
            current += 1
        else:
            current = 1
        if current > longest:
            longest = current
    return longest

